args.CommandLine:
"$paths = @(
  "$env:USERPROFILE\.gemini",
  "$env:APPDATA",
  "$env:LOCALAPPDATA\Programs",
  "$env:LOCALAPPDATA",
  "D:\项目session\00-active-tools",
  "$env:USERPROFILE"
)
foreach ($p in $paths) {
  if (Test-Path $p) {
    Get-ChildItem -Path $p -Filter "*open*design*" -ErrorAction SilentlyContinue | Select-Object FullName, LastWriteTime
    Get-ChildItem -Path $p -Filter "*motion*" -ErrorAction SilentlyContinue | Select-Object FullName, LastWriteTime
  }
}
if (Test-Path "$env:USERPROFILE\.gemini\antigravity\mcp_config.json") {
  Get-Content "$env:USERPROFILE\.gemini\antigravity\mcp_config.json"
}
Get-ChildItem "$env:USERPROFILE\.gemini" -Recurse -Depth 2 -ErrorAction SilentlyContinue | Select-Object FullName"

"Get-ChildItem "C:\Users\86052\AppData\Roaming\Open Design" -Force -ErrorAction SilentlyContinue
Get-Command od -ErrorAction SilentlyContinue
Get-ChildItem "$env:LOCALAPPDATA\Programs" -ErrorAction SilentlyContinue | Where-Object { $_.Name -match "open|design" }
Get-ChildItem "C:\Program Files" -ErrorAction SilentlyContinue | Where-Object { $_.Name -match "open|design" }
Get-Process | Where-Object { $_.ProcessName -match "open|design|od|motion" } | Select-Object Id, ProcessName, Path
if (Test-Path "$env:USERPROFILE\.open-design") { Get-ChildItem "$env:USERPROFILE\.open-design" -Force }
if (Test-Path "$env:USERPROFILE\.opendesign") { Get-ChildItem "$env:USERPROFILE\.opendesign" -Force }
if (Test-Path "$env:USERPROFILE\.claude.json") { Select-String -Path "$env:USERPROFILE\.claude.json" -Pattern "open-design|opendesign|motion" -Context 3,5 }"

